alter table public.calificaciones add constraint "calificaciones_cliente_id_fkey" FOREIGN KEY (cliente_id) REFERENCES usuarios(id) ON DELETE CASCADE;
alter table public.calificaciones add constraint "calificaciones_estrellas_check" CHECK (((estrellas >= 1) AND (estrellas <= 5)));
alter table public.calificaciones add constraint "calificaciones_pedido_id_fkey" FOREIGN KEY (pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE;
alter table public.calificaciones add constraint "calificaciones_socio_id_fkey" FOREIGN KEY (socio_id) REFERENCES usuarios(id) ON DELETE CASCADE;
alter table public.clientes add constraint "clientes_email_key" UNIQUE (email);
alter table public.disputas add constraint "disputas_creado_por_fkey" FOREIGN KEY (creado_por) REFERENCES usuarios(id);
alter table public.disputas add constraint "disputas_pedido_id_fkey" FOREIGN KEY (pedido_id) REFERENCES pedidos(id);
alter table public.especialidades add constraint "especialidades_nombre_key" UNIQUE (nombre);
alter table public.foro add constraint "foro_autor_id_fkey" FOREIGN KEY (autor_id) REFERENCES usuarios(id) ON DELETE CASCADE;
alter table public.foro add constraint "foro_parent_id_fkey" FOREIGN KEY (parent_id) REFERENCES foro(id);
alter table public.mensajes add constraint "mensajes_pedido_id_fkey" FOREIGN KEY (pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE;
alter table public.mensajes add constraint "mensajes_rol_check" CHECK ((rol = ANY (ARRAY['cliente'::text, 'socio'::text])));
alter table public.ofertas add constraint "ofertas_estado_check" CHECK ((estado = ANY (ARRAY['pendiente'::text, 'aceptada'::text, 'rechazada'::text, 'negociando'::text])));
alter table public.ofertas add constraint "ofertas_pedido_id_fkey" FOREIGN KEY (pedido_id) REFERENCES pedidos(id) ON DELETE CASCADE;
alter table public.ofertas add constraint "ofertas_socio_id_fkey" FOREIGN KEY (socio_id) REFERENCES usuarios(id) ON DELETE CASCADE;
alter table public.password_reset_tokens add constraint "password_reset_tokens_token_key" UNIQUE (token);
alter table public.pedidos add constraint "pedidos_cliente_id_fkey" FOREIGN KEY (cliente_id) REFERENCES clientes(id);
alter table public.pedidos add constraint "pedidos_profesional_id_fkey" FOREIGN KEY (profesional_id) REFERENCES usuarios(id);
alter table public.pedidos add constraint "pedidos_socio_preferido_id_fkey" FOREIGN KEY (socio_preferido_id) REFERENCES usuarios(id);
alter table public.pedidos add constraint "pedidos_usuario_id_fkey" FOREIGN KEY (usuario_id) REFERENCES usuarios(id);
alter table public.profesionales add constraint "profesionales_email_key" UNIQUE (email);
alter table public.relaciones_socio add constraint "relaciones_socio_cliente_id_fkey" FOREIGN KEY (cliente_id) REFERENCES usuarios(id) ON DELETE CASCADE;
alter table public.relaciones_socio add constraint "relaciones_socio_cliente_id_socio_id_key" UNIQUE (cliente_id, socio_id);
alter table public.relaciones_socio add constraint "relaciones_socio_socio_id_fkey" FOREIGN KEY (socio_id) REFERENCES usuarios(id) ON DELETE CASCADE;
alter table public.solicitudes_matricula add constraint "solicitudes_matricula_socio_id_fkey" FOREIGN KEY (socio_id) REFERENCES usuarios(id);
alter table public.ubicaciones add constraint "ubicaciones_usuario_id_fkey" FOREIGN KEY (usuario_id) REFERENCES usuarios(id) ON DELETE CASCADE;
alter table public.usuarios add constraint "usuarios_email_key" UNIQUE (email);
alter table public.usuarios add constraint "usuarios_estado_check" CHECK ((estado = ANY (ARRAY['pendiente'::text, 'aprobado'::text, 'rechazado'::text])));
alter table public.usuarios add constraint "usuarios_nombre_usuario_key" UNIQUE (nombre_usuario);
alter table public.usuarios add constraint "usuarios_tipo_check" CHECK ((tipo = ANY (ARRAY['cliente'::text, 'socio'::text, 'admin'::text])));
alter table public.verificaciones_identidad add constraint "verificaciones_identidad_socio_id_fkey" FOREIGN KEY (socio_id) REFERENCES usuarios(id) ON DELETE CASCADE;
